const body = $input.first().json.body;
const entry = body?.entry?.[0];
const messaging = entry?.messaging?.[0];
const ourAccountId = entry?.id;

if (
  !messaging ||
  !messaging.message ||
  messaging.message.is_echo ||
  !messaging.message.text ||
  messaging.sender?.id === ourAccountId
) {
  return [];
}

const mid = messaging.message.mid;

const staticData = $getWorkflowStaticData('node');
staticData.processedMessageIds = staticData.processedMessageIds || {};
if (mid && staticData.processedMessageIds[mid]) {
  return [];
}
if (mid) {
  staticData.processedMessageIds[mid] = true;
}

return [{
  json: {
    senderId: messaging.sender.id,
    recipientId: messaging.recipient.id,
    messageText: messaging.message.text,
    messageId: mid,
  },
}];

const conv = $input.first().json;
const senderId = $('Parse Evento Instagram').item.json.senderId;
const conversations = conv.data || [];

// Não pega cegamente a primeira conversa (limit=1) — procura a que realmente contém
// quem mandou a mensagem atual, senão o bot pode responder pra pessoa errada quando
// há várias conversas ativas ao mesmo tempo (bug real documentado no projeto-base).
let resolvedId = null;
for (const conversation of conversations) {
  const participants = conversation.participants ? conversation.participants.data : [];
  const match = participants.find((p) => p.id === senderId);
  if (match) {
    const other = participants.find((p) => p.id !== $('Config').item.json.igUserId);
    resolvedId = other ? other.id : senderId;
    break;
  }
}

return [{
  json: {
    ...$('Parse Evento Instagram').item.json,
    recipientId: resolvedId || senderId,
  },
}];

const profile = $json;
const evt = $('Extrair PSID').item.json;
return [{
  json: {
    senderId: evt.recipientId,
    messageId: evt.messageId,
    content: evt.messageText,
    customerName: profile.username || undefined,
    profilePictureUrl: profile.profile_pic || undefined,
  },
}];

const body = $input.first().json.body;
const entry = body?.entry?.[0];
const change = entry?.changes?.find((c) => c.field === 'comments');
const ourAccountId = entry?.id;

if (!change) {
  return [];
}

const value = change.value;

if (!value || !value.id || value.from?.id === ourAccountId) {
  return [];
}

const commentId = value.id;

const staticData = $getWorkflowStaticData('node');
staticData.processedCommentIds = staticData.processedCommentIds || {};
if (staticData.processedCommentIds[commentId]) {
  return [];
}
staticData.processedCommentIds[commentId] = true;

return [{
  json: {
    commentId,
    commentText: value.text || '',
    commenterId: value.from?.id || null,
  },
}];
